create temporary table december_tournament_seed (
 slug text not null,name text not null,city text not null,country_code text not null,category_code text not null,surface text not null,environment text not null,season_week smallint not null,phase text not null,slot_order smallint not null,is_fictional boolean not null,continent text not null
) on commit drop;
