do $$ begin
 if exists (select 1 from (select distinct slug,name from december_tournament_seed) s join public.tournament_series t on lower(btrim(t.name))=lower(btrim(s.name)) and t.slug<>s.slug) then raise exception 'December tournament name conflict'; end if;
 if exists (select 1 from (select distinct slug,city from december_tournament_seed) s join public.tournament_series t on lower(btrim(t.city))=lower(btrim(s.city)) and t.slug<>s.slug) then raise exception 'December fictional city conflict'; end if;
 if (select count(distinct slug) from december_tournament_seed)<>24 then raise exception 'Expected 24 December tournaments'; end if;
 if exists (select season_week from december_tournament_seed group by season_week having count(distinct continent)<>6 or count(distinct slug)<>6) then raise exception 'December continent balance invalid'; end if;
end $$;
insert into public.tournament_series (slug,name,city,country_code,category_code,surface,environment) select distinct slug,name,city,country_code,category_code,surface,environment from december_tournament_seed on conflict (slug) do update set name=excluded.name,city=excluded.city,country_code=excluded.country_code,category_code=excluded.category_code,surface=excluded.surface,environment=excluded.environment,is_active=true;
insert into public.tournament_editions (tournament_series_id,season_number) select distinct ts.id,1 from december_tournament_seed s join public.tournament_series ts on ts.slug=s.slug on conflict (tournament_series_id,season_number) do nothing;
insert into public.tournament_world_competitions (tournament_edition_id,world) select distinct e.id,w.world from december_tournament_seed s join public.tournament_series ts on ts.slug=s.slug join public.tournament_editions e on e.tournament_series_id=ts.id and e.season_number=1 cross join (values ('ATP'),('WTA')) w(world) on conflict (tournament_edition_id,world) do nothing;
insert into public.tournament_schedule_slots (tournament_edition_id,calendar_month,month_week,season_week,phase,slot_order) select e.id,12,greatest(1,least(5,s.season_week-48))::smallint,s.season_week,s.phase,s.slot_order from december_tournament_seed s join public.tournament_series ts on ts.slug=s.slug join public.tournament_editions e on e.tournament_series_id=ts.id and e.season_number=1 on conflict (tournament_edition_id,season_week,phase) do update set calendar_month=excluded.calendar_month,month_week=excluded.month_week,slot_order=excluded.slot_order;
do $$ declare a int;b int;c int; begin select count(distinct ts.id) into a from december_tournament_seed s join public.tournament_series ts on ts.slug=s.slug; select count(*) into b from public.tournament_schedule_slots sl join public.tournament_editions e on e.id=sl.tournament_edition_id and e.season_number=1 join public.tournament_series ts on ts.id=e.tournament_series_id where ts.slug in (select distinct slug from december_tournament_seed) and sl.season_week between 49 and 52; select count(*) into c from public.tournament_world_competitions wc join public.tournament_editions e on e.id=wc.tournament_edition_id and e.season_number=1 join public.tournament_series ts on ts.id=e.tournament_series_id where ts.slug in (select distinct slug from december_tournament_seed); if a<>24 then raise exception 'Expected 24 December series, found %',a; end if; if b<>24 then raise exception 'Expected 24 December slots, found %',b; end if; if c<>48 then raise exception 'Expected 48 December competitions, found %',c; end if; end $$;